///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name etnChangePage
 * @description etn Change Page 처리
 * @param {*} tab tab
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.etnChangePage = async function (tab) {
    scwin.form = (document.etnListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_EtnChangePageReq').get('lastSaveStatCd'));
    if (lastSaveStatCdInt === 0 && tab > 1) {
        await $c.win.alert('발행증권에 관한 사항을 먼저 저장해주세요.');
        return;
    } else {
        if (lastSaveStatCdInt === 1 && tab > 2) {
            await $c.win.alert('발행회사에 관한 사항을 먼저 저장해주세요.');
            return;
        } else {
            if (lastSaveStatCdInt === 2 && tab > 3) {
                await $c.win.alert('보증인/제3자LP에 관한 사항을 먼저 저장해주세요.');
                return;
            }
        }
    }
    if (tab === 1) {
        return;
    } else {
        if (tab === 2) {
            $c.util.getComponent('dma_EtnChangePageReq').set('method', 'viewIsurTab');
        } else {
            if (tab === 3) {
                $c.util.getComponent('dma_EtnChangePageReq').set('method', 'viewSrtyLpTab');
            } else {
                $c.util.getComponent('dma_EtnChangePageReq').set('method', 'viewAttachFileTab');
            }
        }
    }
    scwin.form.action = 'EtnList.do';
    await scwin.tx_fn_EtnChangePage();
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (!await scwin.confirmJob('I')) {
        return;
    }
    scwin.removeComma(1);
    if (!fn_validate(1)) {
        return;
    }
    fn_getBzDate();
    if ($c.util.getComponent('cal_lsttrdDd').getValue() !== date1) {
        await $c.win.alert('최종거래일은 만기일(T) 기준 T-2일 이어야 합니다.');
        $c.util.getComponent("cal_lsttrdDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return;
    } else {
        if ($c.util.getComponent('cal_expRedmptAmtPayDd').getValue() < date2) {
            await $c.win.alert('만기상환금 지급일은 만기일(T) 기준 T+2일보다 작으면 안됩니다.');
            $c.util.getComponent("cal_expRedmptAmtPayDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
            return;
        }
    }
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = 'EtnList.do';
    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'saveIsuTab');
    await scwin.tx_fn_Register();
};

/**
 * @method
 * @name etnSub
 * @description etn Sub 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.etnSub = async function () {
    if (!await scwin.confirmJob('S')) {
        return;
    }
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = "EtnList.do";
    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'submitList');
    await scwin.tx_fn_EtnSub();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
