 */
scwin.search = async function () {
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = "EtnList.do";
    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'searchList');
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name fnForwdIdxCd
 * @description fn Forwd Idx Cd 처리
 * @param {*} idxCdVal idxCdVal
 * @param {*} idxCdNmVal idxCdNmVal
 * @returns {void}
 * @hidden N
 */
scwin.fnForwdIdxCd = function (idxCdVal, idxCdNmVal) {
    if (idxCdVal == null || idxCdVal == null) {
        return;
    }
    const idxLvrgInvrsTpCd = idxCdVal.substring(11, 13);
    if (idxLvrgInvrsTpCd === 'P1') {
        $('select[name=forwdIdxCd]').find('option').remove();
        $('select[name=forwdIdxCd]').append('<option value="' + idxCdVal + '">' + idxCdNmVal + '</option>');
    } else {
        const readData_forwdIdxCd = $c.util.getComponent('slc_forwdIdxCd').getValue();
        $('select[name=forwdIdxCd]').find('option').remove();
        for (let i = 0; i < (function(){ throw 'unresolved:list:forwdIdxCd'; })(); i++) {
            const code = (String(((function(){ throw 'unresolved:list:forwdIdxCd'; })()) == null ? '' : ((function(){ throw 'unresolved:list:forwdIdxCd'; })())).indexOf('$' + '{') >= 0 ? '' : String(((function(){ throw 'unresolved:list:forwdIdxCd'; })()) == null ? '' : ((function(){ throw 'unresolved:list:forwdIdxCd'; })())));
            const nm = (String(((function(){ throw 'unresolved:list:forwdIdxCd'; })()) == null ? '' : ((function(){ throw 'unresolved:list:forwdIdxCd'; })())).indexOf('$' + '{') >= 0 ? '' : String(((function(){ throw 'unresolved:list:forwdIdxCd'; })()) == null ? '' : ((function(){ throw 'unresolved:list:forwdIdxCd'; })())));
            let selVal = '';
            if (code.substring(0, 13) === readData_forwdIdxCd.substring(0, 13)) {
                selVal = 'selected';
            }
            $('select[name=forwdIdxCd]').append('<option value="' + code + '" ' + selVal + '>' + nm + '</option>');
        }
    }
};

/**
 * @method
 * @name fnNewProdPrtYn
 * @description fn New Prod Prt Yn 처리
 * @param {*} idxCdVal idxCdVal
 * @returns {void}
 * @hidden N
 */
scwin.fnNewProdPrtYn = function (idxCdVal) {
    if (idxCdVal == null || idxCdVal == null) {
        return;
    }
    const idxLvrgInvrsTpCd = idxCdVal.substring(11, 13);
    if (idxLvrgInvrsTpCd === 'P1') {
        const readData_newProdPrtYn = $c.util.getComponent('slc_newProdPrtYn').getValue();
        const readData_etp_idxIndCd = '' + dma_readDataVO.get("etp_idxIndCd") + '';
        let selVal = '';
        if ('Y' === readData_newProdPrtYn && idxCdVal.substring(0, 13) === readData_etp_idxIndCd) {
            selVal = 'selected';
        }
        $('select[name=newProdPrtYn]').find('option').remove();
        $('select[name=newProdPrtYn]').append('<option value="N">미신청</option>');
        $('select[name=newProdPrtYn]').append('<option value="Y" ' + selVal + '>신청</option>');
    } else {
        $('select[name=newProdPrtYn]').find('option').remove();
        $('select[name=newProdPrtYn]').append('<option value="N">미신청</option>');
    }
};

/**
 * @method
 * @name fnSetOnload
 * @description fn Set Onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnSetOnload = function () {
    const idxSelect = (document.etnListForm || { elements: [] }).etp_idxIndCd;
    const idxIndex = idxSelect.selectedIndex;
    const idxCdVal = idxSelect.options[idxIndex].value;
    const idxCdNmVal = idxSelect.options[idxIndex].text;
    if (idxCdVal !== '' && idxCdVal != null && idxCdVal != null) {
        scwin.fnForwdIdxCd(idxCdVal, idxCdNmVal);
        scwin.fnNewProdPrtYn(idxCdVal);
    }
};

/**
 * @method
 * @name removeComma
 * @description remove Comma 처리
 * @param {*} tab tab
 * @returns {void}
 * @hidden N
 */
scwin.removeComma = function (tab) {

    scwin.form = (document.etnListForm || { elements: [] });
    const elem = $c.util.getComponent('etnListForm').elements;

    if(tab === 1) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('etnIsuQty') >= 0 ||
                elem[i].name.indexOf('isuOrgnVal') >= 0 ||
                // elem[i].name.indexOf('traceYdMult') >= 0 ||
                elem[i].name.indexOf('lpHdQty') >= 0 ||
                elem[i].name.indexOf('declSpd') >= 0 ||
                elem[i].name.indexOf('halfwyRedmptUnit') >= 0 ||
                elem[i].name.indexOf('etnIsuPrc') >= 0
            ) fn_ObjValueResetRmComma2(elem[i]);
        }
    } else if(tab === 2) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('totAsstAmt') >= 0 ||
                elem[i].name.indexOf('totDebtAmt') >= 0 ||
                elem[i].name.indexOf('totCap') >= 0 ||
                elem[i].name.indexOf('cap') >= 0 ||
                elem[i].name.indexOf('bzProftAmt') >= 0 ||
                elem[i].name.indexOf('ordnincmAmt') >= 0 ||
                elem[i].name.indexOf('netincmAmt') >= 0 ||
                elem[i].name.indexOf('bzActivCashFlowAmt') >= 0 ||
                elem[i].name.indexOf('fbzNetcap') >= 0 ||
                elem[i].name.indexOf('totRiskAmt') >= 0 ||
                elem[i].name.indexOf('reqPersisPrincCapVal') >= 0 ||
                (elem[i].name.indexOf('ncr') >= 0 && elem[i].name.indexOf('ncrAcntclsYymm') < 0) ||
                elem[i].name.indexOf('eqtycap') >= 0 ||
                elem[i].name.indexOf('isuTotamt') >= 0 ||
                elem[i].name.indexOf('isuLimit') >= 0
            ) fn_ObjValueResetRmComma2(elem[i]);
        }
    } else if(tab === 3) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('totAsstAmt') >= 0 ||
                elem[i].name.indexOf('totDebtAmt') >= 0 ||
                elem[i].name.indexOf('totCap') >= 0 ||
                elem[i].name.indexOf('cap') >= 0 ||
                elem[i].name.indexOf('bzProftAmt') >= 0 ||
                elem[i].name.indexOf('ordnincmAmt') >= 0 ||
                elem[i].name.indexOf('netincmAmt') >= 0 ||
                elem[i].name.indexOf('bzActivCashFlowAmt') >= 0 ||
                elem[i].name.indexOf('basEqtycap') >= 0 ||
                elem[i].name.indexOf('riskAsstVal') >= 0 ||
                elem[i].name.indexOf('etnSrtyPrincCapRto') >= 0 ||
                elem[i].name.indexOf('srtyEqtycap') >= 0 ||
                elem[i].name.indexOf('srtyIsuTotamt') >= 0 ||
                elem[i].name.indexOf('srtyMiscIsuAmt') >= 0 ||
                elem[i].name.indexOf('srtyIsuLimit') >= 0 ||
                elem[i].name.indexOf('lpFbzNetcap') >= 0 ||
                elem[i].name.indexOf('lpTotRiskAmt') >= 0 ||
                elem[i].name.indexOf('lpReqPersisPrincCapVal') >= 0 ||
                elem[i].name.indexOf('lpNcr') >= 0
            ) fn_ObjValueResetRmComma2(elem[i]);
        }
    }
};

// [A] 초기 목록 미해결 — jldfil70302: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name confirmJob
 * @description 업무 처리 확인 — "[저장] 하시겠습니까?" 확인창(as-is 공통 fn_isProcess 의 의미 보존 · pcc/fil 반입 후보)
 * @param {*} gubun 처리 구분(I 저장 · U 수정 · D 삭제 · S 제출 · R 해제 · DSCL 안내문작성)
 * @returns {Promise<Boolean>} 확인이면 true
 * @hidden N
 */
scwin.confirmJob = async function (gubun) {
    const job = { I: "저장", U: "수정", D: "삭제", S: "제출", R: "해제", DSCL: "안내문작성" }[gubun] || gubun;
    scwin.lastJob = job;  // 결과 알림(alertJobResult)이 같은 처리명을 쓴다 — as-is 전역 LastJob
    return $c.win.confirm("[" + job + "] 하시겠습니까?");
};
